"""Certify independent blocks of sparse inequations on one occupied torus."""
from sympy import Matrix, eye, zeros
from sympy.matrices.normalforms import hermite_normal_form


def lattice_index(order, rows, n):
    """Index in Z^n of the row lattice generated by rows and order*I."""
    if not n:
        return 1
    matrix = Matrix(len(rows), n, [int(v) % order for row in rows for v in row])
    h = hermite_normal_form(matrix.T.row_join(order * eye(n)), D=order**n)
    return int(h.det())


def independent_blocks(order, n, base, groups):
    """Certify that the differences in the specified blocks vary independently.

    base comprises torus equation exponent rows. groups[b] comprises all
    within-factor exponent differences from inequalities belonging to block b.
    The caller separately verifies that the base torsor has a solution.
    """
    base = list(base)
    groups = [list(block) for block in groups]
    if order < 1 or n < 0 or any(len(row) != n for rows in [base, *groups] for row in rows):
        raise ValueError('invalid cyclic group dimensions')
    initial = lattice_index(order, base, n)
    marginal = [initial // lattice_index(order, base + block, n) for block in groups]
    combined = initial // lattice_index(order, base + sum(groups, []), n)
    from math import prod
    return combined == prod(marginal), combined, marginal


if __name__ == '__main__':
    from itertools import product
    from random import Random
    from math import prod
    rng = Random(38155)
    checked = 0
    for order in (1, 3, 7, 15):
        for n in range(1, 4):
            for _ in range(12):
                def rows():
                    return [tuple(rng.randrange(order) for _ in range(n))
                            for _ in range(rng.randrange(3))]
                base = rows()
                blocks = [rows(), rows(), rows()]
                def apply(row, x):
                    return sum(a * b for a, b in zip(row, x)) % order
                joint = {tuple(tuple(apply(a, x) for a in block) for block in blocks)
                         for x in product(range(order), repeat=n)
                         if all(apply(a, x) == 0 for a in base)}
                marginal = [len({entry[i] for entry in joint}) for i in range(len(blocks))]
                assert independent_blocks(order, n, base, blocks) == (
                    len(joint) == prod(marginal), len(joint), marginal)
                checked += 1
    n = 12
    edges = [[tuple(int(i == j) - int(i == j+1) for i in range(n))] for j in range(n-1)]
    assert independent_blocks(3, n, [], edges) == (True, 3**(n-1), [3]*(n-1))
    closing = [[tuple(int(i == 0) - int(i == n-1) for i in range(n))]]
    assert not independent_blocks(3, n, [], edges+closing)[0]
    print(checked, 'character-image checks and torus forest/cycle controls passed')
